use crate::{expr::Expr, types::TypeInfo};
use super::{MlirBuilder, Ref, RefKind};

impl<'a> MlirBuilder<'a> {
    pub(crate) fn address_of_expr(&mut self,e:&Expr)->Result<Ref,String>{match e{Expr::Argument(i)=>{let t=self.closure.arguments.get(*i).cloned().ok_or_else(||"argument index out of bounds".to_string())?;if self.dynamic{let idx=self.c_i64(*i as i64);let p=self.gep_raw("%args","ptr",&idx);Ok(Ref{name:self.load_raw(&p,"!llvm.ptr"),ty:t,kind:RefKind::Address})}else{let at=TypeInfo::Struct{name:"args".into(),fields:self.closure.arguments.iter().enumerate().map(|(i,t)|crate::types::FieldInfo{name:i.to_string(),type_info:t.clone()}).collect()};Ok(Ref{name:self.gep_const("%args",&at,&[0,*i]),ty:t,kind:RefKind::Address})}},Expr::Field{object,name}=>{let base=self.address_of_expr(object)?;let fields=match &base.ty{TypeInfo::Struct{fields,..}=>fields,_=>return Err("field access requires a struct".to_string())};let(i,f)=fields.iter().enumerate().find(|(_,f)|f.name==*name).ok_or_else(||format!("field `{}` not found",name))?;Ok(Ref{name:self.gep_const(&base.name,&base.ty,&[0,i]),ty:f.type_info.clone(),kind:RefKind::Address})},Expr::Index{sequence,index}=>self.index_address(sequence,index),_=>Err("expression is not addressable".to_string())}}
    pub(crate) fn lower_ref(&mut self,e:&Expr,expected:&TypeInfo)->Result<Ref,String>{if let Ok(a)=self.address_of_expr(e){let v=self.load(&a.name,&a.ty);return Ok(Ref{name:v,ty:a.ty,kind:RefKind::Value})}self.lower_expr(e,expected)}
    pub(crate) fn index_address(&mut self,sequence:&Expr,index:&Expr)->Result<Ref,String>{let base=self.address_of_expr(sequence)?;let idx=self.lower_expr(index,&TypeInfo::Usize)?.name;match &base.ty{TypeInfo::Array{element,length}=>{let len=self.c_i64(*length as i64);self.bounds(&idx,&len)?;Ok(Ref{name:self.gep_array_dynamic(&base.name,&base.ty,&idx),ty:(**element).clone(),kind:RefKind::Address})},TypeInfo::Slice{element}=>{let data_p=self.gep_const(&base.name,&base.ty,&[0,0]);let len_p=self.gep_const(&base.name,&base.ty,&[0,1]);let data=self.load_raw(&data_p,"!llvm.ptr");let len=self.load(&len_p,&TypeInfo::Usize);self.bounds(&idx,&len)?;Ok(Ref{name:self.gep_dynamic(&data,element,&idx),ty:(**element).clone(),kind:RefKind::Address})},_=>Err("indexing requires an indexable sequence".to_string())}}
}
